mapper.select:
with insite_pm_order as ( select 'Insite'::text as issue_type,
from v2_pm_order t LEFT JOIN asset_info a ON t.asset_id = a.id left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid) LEFT join org_info oi on a.site_uid=oi.uid where a.uid is not null AND a.is_valid AND NOT a.is_deleted
), mvs_pm_order as ( select 'MVS'::text as issue_type,
from v2_pm_order t left join mvs_ib_mapping m1 ON t.asset_uid = m1.mvs_ib_uid or t.asset_uid=m1.e_home_ib_uid left join asset_info a ON m1.ib_uid = a.uid left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid) LEFT join org_info oi on a.site_uid=oi.uid WHERE a.uid is not null AND a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NOT NULL OR m1.e_home_ib_uid IS NOT NULL)
), unified_work_order as ( select * from insite_pm_order UNION ALL select * from mvs_pm_order ) select * from unified_work_order ORDER BY plan_time DESC
LIMIT #{pageSize} OFFSET #{offset}

with insite_pm_order as ( select
from v2_pm_order t LEFT JOIN asset_info a ON t.asset_id = a.id left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid) LEFT join org_info oi on a.site_uid=oi.uid where a.uid is not null AND a.is_valid AND NOT a.is_deleted
), mvs_pm_order as ( select
from v2_pm_order t left join mvs_ib_mapping m1 ON t.asset_uid = m1.mvs_ib_uid or t.asset_uid=m1.e_home_ib_uid left join asset_info a ON m1.ib_uid = a.uid left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid) LEFT join org_info oi on a.site_uid=oi.uid WHERE a.uid is not null AND a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NOT NULL OR m1.e_home_ib_uid IS NOT NULL)
) select count(*) from ( select id from insite_pm_order UNION ALL select id from mvs_pm_order ) t
